float phase=Time*BlinkSpeed+(UV.x+UV.y)*BlinkUVScale*6.28318530718;
float blink=lerp(1.0,0.5+0.5*sin(phase),saturate(BlinkWeight));
float horizon=smoothstep(HMin,max(HMax,HMin+1.0),World.z-Center.z);
float3 star=RawStar*lerp(float3(1,1,1),StarColor.rgb,saturate(StarColorWeight))*blink*horizon;
float3 dir=normalize(World.xyz-Center.xyz);
float sun=pow(saturate(dot(dir,normalize(SunDirection.xyz))),1.0/max(SunRadius,0.0001));
float nLuma=dot(NebulaRGB.rgb,float3(0.2126,0.7152,0.0722));
float3 nColor=lerp(NebulaRGB.rgb,float3(nLuma,nLuma,nLuma),saturate(NebulaDesaturation))*NebulaIntensity*NebulaInfluence;
return max(Base.rgb-OldStar.rgb-float3(OldNeb,OldNeb,OldNeb),0.0)+nColor+star+SunColor.rgb*SunIntensity*SunScale*sun;

float2 windowUV = (World.xy-Transform.xy)/max(Transform.z,1.0);
float2 uv = frac(World.xy/max(Transform.z,1.0));
float4 field = Texture2DSampleLevel(Field,FieldSampler,uv,0);
float2 edge = min(windowUV,1.0-windowUV)*Transform.z/max(Transform.w,0.01);
float inside = saturate(min(edge.x,edge.y)/16.0);
inside = inside*inside*(3.0-2.0*inside);
float altitude = 1.0-smoothstep(HeightTolerance*0.75,HeightTolerance,abs(World.z-field.b));
float valid = field.a*inside*altitude;
float requestedDepth = DepthReferenceCm*saturate(field.r);
float depth = min(max(SnowHeight,0.0),requestedDepth)*valid;
float compression = depth/max(SnowHeight,0.00001);
float rim = saturate(field.g)*valid;
float capped = (SnowHeight>0.0 && requestedDepth>=SnowHeight) ? valid : 0.0;
return float4(SnowHeight-depth+RimHeight*rim*SnowMask,compression*SnowMask,rim*SnowMask,capped);

float3 dx=ddx(World), dy=ddy(World);
float determinant=dx.x*dy.y-dx.y*dy.x;
float2 slope=0.0;
if (abs(determinant)>0.00001)
    slope=float2(ddx(SnowHeight)*dy.y-ddy(SnowHeight)*dx.y,
                 ddy(SnowHeight)*dx.x-ddx(SnowHeight)*dy.x)/determinant;
slope *= 1.0-FieldValue.w;
if (FieldValue.y+FieldValue.z>0.0)
{
    float stepCm=max(Transform.w*2.0,0.01);
    float2 uv=frac(World.xy/max(Transform.z,1.0));
    float d=stepCm/max(Transform.z,1.0);
    float4 xp=Texture2DSampleLevel(Field,FieldSampler,uv+float2(d,0),0);
    float4 xm=Texture2DSampleLevel(Field,FieldSampler,uv-float2(d,0),0);
    float4 yp=Texture2DSampleLevel(Field,FieldSampler,uv+float2(0,d),0);
    float4 ym=Texture2DSampleLevel(Field,FieldSampler,uv-float2(0,d),0);
    float4 x=float4(World.x+stepCm,World.x-stepCm,World.x,World.x);
    float4 y=float4(World.y,World.y,World.y+stepCm,World.y-stepCm);
    float4 ex=min(x-Transform.x,Transform.x+Transform.z-x)/max(Transform.w,0.01);
    float4 ey=min(y-Transform.y,Transform.y+Transform.z-y)/max(Transform.w,0.01);
    float4 inside=saturate(min(ex,ey)/16.0);
    inside=inside*inside*(3.0-2.0*inside);
    float4 valid=float4(xp.a,xm.a,yp.a,ym.a)*inside*
        (1.0-smoothstep(HeightTolerance*0.75,HeightTolerance,
                       abs(World.z-float4(xp.b,xm.b,yp.b,ym.b))));
    float4 heights=(-min(max(SnowHeight,0.0),DepthReferenceCm*saturate(float4(xp.r,xm.r,yp.r,ym.r)))+
                   RimHeight*SnowMask*saturate(float4(xp.g,xm.g,yp.g,ym.g)))*valid;
    slope+=float2(heights.x-heights.y,heights.z-heights.w)/(2.0*stepCm);
}
return normalize(BaseNormal+float3(-slope,0.0));
